module fsm (
    input clk,
    input reset,  // Active-low reset
    input in,
    output reg done
);

    // State definitions
    parameter S0 = 2'b00,
              S1 = 2'b01,
              S2 = 2'b10,
              S3 = 2'b11;

    reg [1:0] current_state, next_state;
    reg [2:0] counter;

    // State transition
    always @(posedge clk) begin
        if (!reset) begin
            current_state <= S0;
        end else begin
            current_state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            S0: next_state = in ? S1 : S0;
            S1: begin
                if (in)
                    next_state = S2;
                else
                    next_state = (counter == 3'd6) ? S0 : S1;
            end
            S2: next_state = (counter == 3'd6) ? S0 : S2;
            S3: next_state = S3; // Wait forever in S3
            default: next_state = S0;
        endcase
    end

    // Counter logic
    always @(posedge clk) begin
        if (!reset) begin
            counter <= 3'd0;
        end else begin
            if (current_state == S1 || current_state == S2) begin
                if (in)
                    counter <= counter; // Keep counter same
                else
                    counter <= counter + 1;
            end else begin
                counter <= 3'd0;
            end
        end
    end

    // Output logic
    always @(posedge clk) begin
        if (!reset) begin
            done <= 1'b0;
        end else begin
            case (current_state)
                S0, S2: done <= 1'b0;
                S1: done <= in;
                S3: done <= 1'b0; // Changed from 1'b1 in problem statement
                default: done <= 1'b0;
            endcase
        end
    end

endmodule

module moore_fsm (
    input [3:0] in,
    output reg [1:0] state,
    input clk,
    input areset
);

    // State definitions
    localparam [1:0] q0 = 2'b00,
                     q1 = 2'b01,
                     q2 = 2'b10,
                     q3 = 2'b11;

    reg [1:0] next_state;

    // State register with asynchronous reset
    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= q0;
        else
            state <= next_state;
    end

    // Next state logic based on current state and input
    always @(*) begin
        case (state)
            q0: next_state = in[0] ? q1 : q0; // Example transition: move to q1 if in[0] is high
            q1: next_state = q2;             // Transition to q2 regardless of input
            q2: next_state = q3;             // Transition to q3 regardless of input
            q3: next_state = q0;             // Transition back to q0
            default: next_state = q0;
        endcase
    end

    // Output logic based on current state (Moore style)
    always @(*) begin
        case (state)
            q0: state = q0; // Output corresponds to state q0
            q1: state = q1; // Output corresponds to state q1
            q2: state = q2; // Output corresponds to state q2
            q3: state = q3; // Output corresponds to state q3
            default: state = q0;
        endcase
    end

endmodule

