module decoder3to8(input [2:0] in, input enable, output [7:0] out);
    reg [3:0] state;

    always @(posedge enable) begin
        case (state)
            4'd0: state <= (in[0] | in[1]) ? 4'd1 : 4'd0;
            4'd1: state <= (in[0] | in[2]) ? 4'd2 : 4'd1;
            4'd2: state <= (in[1] | in[2]) ? 4'd3 : 4'd2;
            4'd3: state <= in[2] ? 4'd0 : 4'd3;
            default: state <= 4'd0;
        endcase
    end

    assign out[0] = (state == 4'd0);
    assign out[1] = (state == 4'd1);
    assign out[2] = (state == 4'd2);
    assign out[3] = (state == 4'd3);
    assign out[4] = (state == 4'd0);
    assign out[5] = (state == 4'd1);
    assign out[6] = (state == 4'd2);
    assign out[7] = (state == 4'd3);

endmodule

