  input areset,
  input train_valid,
  input train_taken,
  output logic [1:0] state
);

  parameter [1:0] IDLE = 2'b00,
                  CAPTURE = 2'b01,
                  TRANSFER = 2'b10,
                  COMPLEMENT = 2'b11;

  reg [1:0] current_state, next_state;

  assign state = current_state;

  always @(posedge clk) begin
    if (areset)
      current_state <= IDLE;
    else
      current_state <= next_state;
  end

  always @(*) begin
    case (current_state)
      IDLE:   next_state = train_valid ? CAPTURE : IDLE;
      CAPTURE: next_state = TRANSFER;
      TRANSFER: next_state = train_taken ? COMPLEMENT : TRANSFER;
      COMPLEMENT: next_state = IDLE;
      default: next_state = IDLE;
    endcase
  end

endmodule

